<script type="application/json" id="kh-posts">[{"date": "2026/10/11", "url": "https://x.com/karin__miyamoto/status/2109063104063750517", "song": "泣いちゃうかも", "artist": "モーニング娘。", "text": "16ビート取れてないと踊れない振り付けの曲。\n「泣いちゃうかも」じゃなくて\n「ん泣いちゃうかも」なんだよね、、\n歌詞にない「ん」が聞こえるところからが\nハロヲタの入口なのかもしれません。"}, {"date": "2026/10/10", "url": "https://x.com/karin__miyamoto/status/2108712269102330262", "song": "SONGS", "artist": "モーニング娘。", "text": "こんなにワクワクするイントロがあるだろうか。。\nつんく♂さんが、アイドルになりたいと言った人はオーディションで落ちてる、歌手だから、と話していたことがあったような。\nこの曲を歌いこなせるって、やはり歌手なんだよね！"}, {"date": "2026/10/09", "url": "https://x.com/karin__miyamoto/status/2108352961479160091", "song": "世界一HAPPYな女の子", "artist": "℃-ute", "text": "片足立ちで跳ねながら歌うところがあるんだけど、\nハロプロだ…ってなる難易度だよね😂\n\nあとジャケ写よりMVのイメージ強すぎる！！！"}, {"date": "2026/10/08", "url": "https://x.com/karin__miyamoto/status/2108112267158139308", "song": "君の友達", "artist": "Berryz工房", "text": "一人称「僕」がいちばんハマるアイドルグループって\nBerryz工房さんだよね！？"}, {"date": "2026/10/07", "url": "https://x.com/karin__miyamoto/status/2107612006794826236", "song": "消失点-Vanishing Point-", "artist": "Buono!", "text": "Buono!さんのアルバムを聴いて\n歌いたいなぁと思った曲。\nハロプロメンバーの琴線に触れる曲だからなのか、\nバーイベ常連曲な気がする☺️"}, {"date": "2026/10/06", "url": "https://x.com/karin__miyamoto/status/2107325229781635497", "song": "スキちゃん", "artist": "スマイレージ", "text": "たぶんMVでしか見られないよねってくらい\nイントロのクラップが定着しているけど\nイントロの振り付け、好きなんだよなぁ☺️"}, {"date": "2026/10/04", "url": "https://x.com/karin__miyamoto/status/2106558547115036675", "song": "私の心", "artist": "スマイレージ", "text": "この曲は聴いた時に\nバースデーイベントで絶対歌う！！\nと思って歌った記憶😂\nバーイベ常連曲だよね！？"}, {"date": "2026/10/02", "url": "https://x.com/karin__miyamoto/status/2105891846555938854", "song": "海岸清掃男子", "artist": "HI-FIN", "text": "SATOYAMA&SATOUMI曲の中でかなり好き。\n「あ！見つけた空き缶！」のセリフでようやくSATOUMI曲ってことを思い出す😂"}, {"date": "2026/10/01", "url": "https://x.com/karin__miyamoto/status/2105511585955639670", "song": "恋愛ハンター", "artist": "モーニング娘。", "text": "ガニ股の振り付けは\nハロプロ名物ですが\n\nこの曲のガニ股も\nもちろん好きです。😂\n\n誰より腰の位置を下げる！！！\nこれが大事！！！😂\n\nこれもバックダンサーした気がする…！"}, {"date": "2026/09/30", "url": "https://x.com/karin__miyamoto/status/2105151193542705477", "song": "チョトマテクダサイ！", "artist": "スマイレージ", "text": "つんく♂さんが中西香菜ちゃんに\nサビの振り付けを\n\n「間違ってる人みたいに遅れて入れ！」\nって指導してるのを見て\n\n面白いなぁと思った記憶。笑\n\nバックダンサーしてた気がする…！"}, {"date": "2026/09/29", "url": "https://x.com/karin__miyamoto/status/2104727934267543811", "song": "踊れ!モーニングカレー", "artist": "モーニング娘。", "text": "このタイトルなのに\nライブだとかっこいいし楽しいんだよ…\n\n想像以上にかっこいいんだよ…\n\nでもカレーかき混ぜる振り付けなのに…\n\nかっこいいの…🍛"}, {"date": "2026/09/28", "url": "https://x.com/karin__miyamoto/status/2104391526604562597", "song": "恋にBooing ブー！", "artist": "スマイレージ", "text": "ハロプロアイドルは\n豚鼻つけてもかわいいのですよ🐷\n\n「もうっ！バカ！」って言ったら\n絶対かわいいの分かってたでしょ！！\n\nつんく♂さん！！！"}, {"date": "2026/09/26", "url": "https://x.com/karin__miyamoto/status/2103654313168146682", "song": "ナルシス カマってちゃん協奏曲第5番", "artist": "モーニング娘。'17", "text": "タイトル、曲調、メロディー、歌詞\n\n全部まとめて\nハロプロにしか無さそうな曲ですね本当に！！！\n\nあとこの時人数多いね！？"}, {"date": "2026/09/24", "url": "https://x.com/karin__miyamoto/status/2102955160335228976", "song": "有頂天LOVE", "artist": "スマイレージ", "text": "人生で1番見たかもしれないMV。\n\nかわいいって\nこういうことなんですよね…\n\nオーディションで歌ったな…\n歌詞間違えたなぁ😂"}, {"date": "2026/09/23", "url": "https://x.com/karin__miyamoto/status/2102555319675314430", "song": "BRAND NEW MORNING", "artist": "モーニング娘。'17", "text": "これ、ハロコン？か何かで\nカバーした気がする…！\n\n覚えてる方いらっしゃいますか…？\n\nグループ名が入ってる曲が\nカバーで回ってくることあるんだ！？って\nびっくりした記憶。"}, {"date": "2026/09/22", "url": "https://x.com/karin__miyamoto/status/2102196054313873535", "song": "この地球の平和を本気で願ってるんだよ！", "artist": "モーニング娘。", "text": "「地平本願」って略したのは\n誰ですか…？笑\n\n全世界で大切にしてほしい\n四字熟語ですね😌"}, {"date": "2026/09/21", "url": "https://x.com/karin__miyamoto/status/2101831321089978701", "song": "WASSUP？遠慮がテーマ", "artist": "ミニモニ。", "text": "いつかライブでやりたいけど\n\nやりますよって言ってからやって\nみんなの全力の「うぉ！」が聞きたい😂\n\nサウンドが\nアイドルソングっぽくないところも好き。"}, {"date": "2026/09/20", "url": "https://x.com/karin__miyamoto/status/2101467544297283591", "song": "100回のKISS", "artist": "松浦亜弥", "text": "松浦さんご本人の歌声も\n楽曲の切なさとリズム感も\nとにかく超大好きな曲なんだけど\n\n前田憂佳ちゃんカバーの\n存在してるか怪しいくらいの天使感が\n一生忘れられません。"}, {"date": "2026/09/19", "url": "https://x.com/karin__miyamoto/status/2101107746124992594", "song": "人間関係No way way", "artist": "モーニング娘。'20", "text": "LOVEペディアと同じメロディーなのは有名ですが\n\nハロコンで一時期\nグループが別グループのバックダンサーをしてたことって知ってる？\n\nバックダンサーしたの\nたしかこの曲だった気がする…！"}, {"date": "2026/09/18", "url": "https://x.com/karin__miyamoto/status/2100745189359038659", "song": "Dream Road〜心が躍り出してる〜", "artist": "Juice=Juice", "text": "植村あかりちゃんがチョコ好きだから\n「チョコのご褒美」の歌詞もらったと思ってるけど\n真相は分からない。笑\n\nあとこの曲の振り付けを\n「大工」って言い始めたの誰ですか？⚒️"}, {"date": "2026/09/17", "url": "https://x.com/karin__miyamoto/status/2100388665612788170", "song": "好きよ、純情反抗期。", "artist": "スマイレージ", "text": "この曲、ハロコンのゲネか何かで\nつんく♂さんに\n「16ビート！！」って\nすごい言われてたなぁ…\n\nぶりぶりしてない可愛い曲ランキング作ったら\n絶対上位なんだろうなぁ😌"}, {"date": "2026/09/16", "url": "https://x.com/karin__miyamoto/status/2100204108976369991", "song": "Everyday Everywhere", "artist": "太陽とシスコムーン", "text": "大人になったらこの曲を歌いたいと\n幼心に思ってた曲リストに入ってます。\n\nもう大人なのに\nちゃんと挑戦できたことは\nまだ無いかもしれない…😌"}, {"date": "2026/09/15", "url": "https://x.com/karin__miyamoto/status/2099658662977667430", "song": "ミニハムずの愛の唄", "artist": "ミニモニ。", "text": "この曲聴くと\n幼い頃にミニモニ。のガチャを回したこと\n思い出すんだよなぁ…\n\nネイルが当たった記憶💅"}, {"date": "2026/09/14", "url": "https://x.com/karin__miyamoto/status/2099308813140844582", "song": "Never Never Surrender", "artist": "Juice=Juice", "text": "この間メンバーに聞いたら\n未だに体力消耗曲ランキングで\n上位をキープしていた曲…！\n\nラストのユニゾンが\n大変なのですよ😂"}, {"date": "2026/07/01", "url": "https://x.com/karin__miyamoto/status/2072155206893396059", "song": "地団駄ダンス", "artist": "Juice=Juice", "text": "マネージャーさんに\nまんまと騙された曲。\n\n「デコ出しハチマキは\nダンスシーンしか映らないから！」と言われたのに\n\n堂々とポスターとジャケットになりました🥁\n\nハロプロに\nデコ出しエピは欠かせない🤦‍♀️"}, {"date": "2026/06/30", "url": "https://x.com/karin__miyamoto/status/2071746528616808505", "song": "こんなハズジャナカッター！", "artist": "BEYOOOOONDS", "text": "グループの自虐ソングが\nこんなに可愛くて面白いことある！？\n\nBEYOOOOONDSって楽しい曲の宝庫。"}, {"date": "2026/06/29", "url": "https://x.com/karin__miyamoto/status/2071427402857898186", "song": "ありがとう！おともだち。", "artist": "Berryz工房", "text": "つんく♂さんあるある。\n\n可愛くて簡単そう！\nカラオケで歌いたい！\n↓\n鬼転調と鬼リズム、難易度MAXで\n挫折しかける。\n\nこの曲もそう…😂"}, {"date": "2026/06/26", "url": "https://x.com/karin__miyamoto/status/2070323018505867353", "song": "普通、アイドル10年やってらんないでしょ！？", "artist": "Berryz工房", "text": "この曲を聴いてた時は\n先輩たちすごいなぁと思ってたのに\n\n私は研修生期間含めて18年経ってしまっていて\n\n「アイドル20年やってらんないでしょ！？」が\n近づいてきている事実😂"}, {"date": "2026/06/22", "url": "https://x.com/karin__miyamoto/status/2068872091609530811", "song": "色っぽい女〜SEXY BABY〜", "artist": "カントリー娘。に石川梨華(モーニング娘｡)", "text": "石川梨華さんの\n色っぽい系の良さって\n凄すぎて普通じゃないと思います…"}, {"date": "2026/06/19", "url": "https://x.com/karin__miyamoto/status/2067805450687672760", "song": "トロピカ〜ル恋して〜る", "artist": "松浦亜弥", "text": "夏の香りがしてくると\nハロプロ夏ソングが\nたくさん聴きたくなるね🌺\n\nみんなの好きなハロプロ夏ソングは？"}, {"date": "2026/06/18", "url": "https://x.com/karin__miyamoto/status/2067410299096100866", "song": "夏 LOVE ロマンス", "artist": "ハロー！プロジェクト", "text": "カバーさせてもらった時\nイントロで鬼ふざけてた記憶ある。笑\n\n波打ち際で水をかけるみたいな振りなのに\n多分バケツでかけまくったり\n投球始めたりしてた😂"}, {"date": "2026/06/17", "url": "https://x.com/karin__miyamoto/status/2067081860451291524", "song": "伸びしろ～Beyond the World～", "artist": "BEYOOOOONDS", "text": "何も言わず\n本日はこの曲で行かせてください。"}, {"date": "2026/06/15", "url": "https://x.com/karin__miyamoto/status/2066316637083754590", "song": "友情 純情 oh 青春", "artist": "Berryz工房", "text": "この曲でライブしたくなってきたぁぁぁ"}, {"date": "2026/06/14", "url": "https://x.com/karin__miyamoto/status/2065949631893451262", "song": "Goal〜明日はあっちだよ〜", "artist": "Juice=Juice", "text": "この曲の振り付け日に\n体調崩して行けなかったの\nめっちゃ覚えてる…\n\n初めての武道館でのこの歌詞は\n沁みたなぁ😌"}, {"date": "2026/06/13", "url": "https://x.com/karin__miyamoto/status/2065580367726407870", "song": "妄想リハーサル", "artist": "カントリー・ガールズ", "text": "カントリー・ガールズの曲って\n本当にいつ聴いても可愛くて\nありがとう。という気持ち😌"}, {"date": "2026/06/12", "url": "https://x.com/karin__miyamoto/status/2065242732390662230", "song": "こんなハズジャナカッター！", "artist": "BEYOOOOONDS", "text": "リズム良くて\nちょい自虐的\n\nアイドルっぽくないのに\nアイドルだしみんな可愛い。"}, {"date": "2026/06/11", "url": "https://x.com/karin__miyamoto/status/2064875390896939177", "song": "イマココカラ", "artist": "モーニング娘。'15", "text": "プリキュア！！って感じするし\n元気出る曲！！\n\n私しれっと参加させてもらったシングルだったんだ！？\nって今知った…ダメすぎる😂"}, {"date": "2026/06/10", "url": "https://x.com/karin__miyamoto/status/2064491925894492163", "song": "幸せですか？", "artist": "セクシー8", "text": "Aメロのバスドラ\nこんな刻み方だっけ！？ってなった😂\n\n改めて聴くと\nリズムも音程も取るのが\nすごく難しそうなオケだなぁ…😌"}, {"date": "2026/06/09", "url": "https://x.com/karin__miyamoto/status/2064149660617551945", "song": "涙が止まらない放課後", "artist": "モーニング娘。", "text": "卒業といえばこの曲、ってなるけど\n卒業曲って\nその時に卒業したメンバーさんの印象が強くなるから\n歌える機会少ないイメージ"}, {"date": "2026/06/08", "url": "https://x.com/karin__miyamoto/status/2063765319009939804", "song": "私を創るのは私", "artist": "アンジュルム", "text": "この曲のタイトル聞いた時に\n他人の影響受けちゃう自分に嫌になってたけど\n\nあ、結局そうだよな\n私を創ってるのは私だわって\n思い返せた曲😌"}, {"date": "2026/06/07", "url": "https://x.com/karin__miyamoto/status/2063420742289768482", "song": "CLAP!", "artist": "Berryz工房", "text": "ライブでこの曲来ると\nガッツポーズしちゃうんだが…😂\n\nみんながガッツポーズしちゃう\nBerryz工房曲はなに？"}, {"date": "2026/06/06", "url": "https://x.com/karin__miyamoto/status/2063052415860179177", "song": "Good Morning", "artist": "モーニング娘。", "text": "いつかのハロコンで踊った気がする…！\n何年のハロコンだったっけ？？？"}, {"date": "2026/06/05", "url": "https://x.com/karin__miyamoto/status/2062710254497038807", "song": "黄昏交差点", "artist": "真野恵里菜", "text": "「真野恵里菜さんで好きな曲は？」ってハロメンに聞くと\nこの曲！って返ってくることが多い気がする…！\n\nうれしい😌"}, {"date": "2026/06/04", "url": "https://x.com/karin__miyamoto/status/2062344989125091446", "song": "やる気！IT'S EASY", "artist": "後藤真希", "text": "大丈夫、きっと大丈夫！！\nって自分に言い聞かせられて\n強くなれる曲。"}, {"date": "2026/06/03", "url": "https://x.com/karin__miyamoto/status/2061986105944363290", "song": "スプリンター！", "artist": "Berryz工房", "text": "もう春終わっちゃったじゃん！！\n私としたことが！！😂"}, {"date": "2026/06/02", "url": "https://x.com/karin__miyamoto/status/2061601874982445098", "song": "Missラブ探偵", "artist": "W", "text": "カプ推しが\nカプで聴きたい曲って\nWに集結してる気がする…😌\n\nロボキッスもそう…！"}, {"date": "2026/05/31", "url": "https://x.com/karin__miyamoto/status/2060888215192830449", "song": "The Vision", "artist": "モーニング娘。'19", "text": "この曲も\n不思議な気持ちの懐かしさになる曲。\n\nAメロBメロ\nどうやって音とるの？ってレベルで\nオケ薄くて改めてびっくりした…😂"}, {"date": "2026/05/30", "url": "https://x.com/karin__miyamoto/status/2060501064986857559", "song": "ドドンガドン音頭", "artist": "℃-ute", "text": "この時のアルバム、この曲だけ超異質なんだよなぁ…\n\nあと生で聴けたことは1度もない。\nいつかどこかで来てほしい😌"}, {"date": "2026/05/29", "url": "https://x.com/karin__miyamoto/status/2060146719044886676", "song": "This is 運命", "artist": "メロン記念日", "text": "ひとりでもリズムがズレたら\n一気に崩れる1文字歌割りがあって…\n地味にめっちゃ難しい曲😌"}, {"date": "2026/05/28", "url": "https://x.com/karin__miyamoto/status/2059815244797768172", "song": "The 美学", "artist": "松浦亜弥", "text": "この曲歌えたら\nもうハロプロ歌唱完成してると思います😂"}, {"date": "2026/05/27", "url": "https://x.com/karin__miyamoto/status/2059419839794761920", "song": "真夏の光線", "artist": "モーニング娘。", "text": "なんか5月なのに\n真夏みたいな日差し来るから\nこの曲選びました😂"}, {"date": "2026/05/26", "url": "https://x.com/karin__miyamoto/status/2059060154021380561", "song": "Give me 愛", "artist": "モーニング娘。", "text": "この曲の高橋愛さんみたいになりたいなって\nすごい思ってた記憶あるなぁ。\n永遠の憧れ。"}, {"date": "2026/05/25", "url": "https://x.com/karin__miyamoto/status/2058697366639882377", "song": "ウルフボーイ", "artist": "モーニング娘。", "text": "この曲聴くと\nショートカットの工藤遥ちゃんが\nめっちゃ浮かんでくるんだよねぇ…\n\nなんでなんだろう？？"}, {"date": "2026/05/24", "url": "https://x.com/karin__miyamoto/status/2058333983298175163", "song": "スマイル美人", "artist": "スマイレージ", "text": "「初恋」を“はつこうぃ”って歌ってて\nハロプロ感じた…！笑\n\n初期スマのハロプロ感\nだぁいすき😌"}, {"date": "2026/05/23", "url": "https://x.com/karin__miyamoto/status/2057984949652009398", "song": "女に 幸あれ", "artist": "モーニング娘。", "text": "「音がハロプロしてる」って\nこういうことだと思うんですよ…\n\n言語化に乏しくてごめんけど、、\n伝わってくれぇ、、😂"}, {"date": "2026/05/22", "url": "https://x.com/karin__miyamoto/status/2057625551196844197", "song": "Never Never know～コメ派とパン派のラブウォーズ～", "artist": "BEYOOOOONDS", "text": "可愛くて面白い曲！\n\nカバーさせていただいたこともあったなぁと思って\nつい選曲しちゃいました☺️\n\nみんなはコメ派？パン派？🍚🥐"}, {"date": "2026/05/21", "url": "https://x.com/karin__miyamoto/status/2057249372992409820", "song": "ええか！？", "artist": "スマイレージ", "text": "この頃のスマ曲、可愛くて好き！\n\nこれダンス部で踊ったことある気がするんだけど\nいつだかは覚えてない…😂"}, {"date": "2026/05/20", "url": "https://x.com/karin__miyamoto/status/2056928700080521505", "song": "ダンシング！夏祭り", "artist": "10人祭", "text": "外が暑すぎて\nこの曲しか思い浮かびませんでした😂\n\n〇人祭り、みんなは全部わかる？"}, {"date": "2026/05/19", "url": "https://x.com/karin__miyamoto/status/2056538740429086760", "song": "今すぐ飛び込む勇気", "artist": "モーニング娘。'15", "text": "この曲大好きで\nハロコンで聴けるの楽しみだった！\n\n白鳥？みたいな振り付けあるよね…？🦢\n\nえ、これ11年前ってこと！？無理😂"}, {"date": "2026/05/18", "url": "https://x.com/karin__miyamoto/status/2056192280231616515", "song": "Help me!!", "artist": "モーニング娘。", "text": "ハロコンでカバーさせてもらったことあるなぁ…！\n\nフォーメーションダンスの難しさ\n思い知った曲。笑\n\nいつだったか忘れた…\n何年だっけ？？"}, {"date": "2026/05/17", "url": "https://x.com/karin__miyamoto/status/2055809032297025892", "song": "はぴ☆はぴ サンデー！", "artist": "月島きらり starring 久住小春（モーニング娘。）", "text": "私の女児心は永遠に\n月島きらりちゃんにくすぐられるんだと思う😌\n\nみんなが好きなきらり曲、教えて！！"}, {"date": "2026/05/16", "url": "https://x.com/karin__miyamoto/status/2055457803867955229", "song": "涙ッチ", "artist": "モーニング娘。", "text": "この曲聴くとちょっと寂しくなるけど\n明日からも頑張らなきゃって思えて好き。\n\nバースデーイベントで歌ったことがあるくらい\n好きな曲です😌"}, {"date": "2026/05/15", "url": "https://x.com/karin__miyamoto/status/2055074185559597485", "song": "TOKYOグライダー", "artist": "Juice=Juice", "text": "この曲が発表された時期\nなんかあったっけ…？\n\nこの曲聴くと\n普通の懐かしさと違う懐かしさがあるんだよなぁ…\nなんだろう😌"}, {"date": "2026/05/13", "url": "https://x.com/karin__miyamoto/status/2054352072901042356", "song": "情熱のキスを一つ", "artist": "モーニング娘。", "text": "このライブ映像見た時\n大人になったら歌うんだ！！って思ってたのに\n\nこの曲の大人っぽさに\nいまだ追いつけないので厳しい…笑\n\n皆さん当時私より年下、、"}, {"date": "2026/05/12", "url": "https://x.com/karin__miyamoto/status/2053989323377451076", "song": "五月雨美女がさ乱れる", "artist": "Juice=Juice", "text": "5月だから忘れぬうちに！！笑\n\n曲を頂いた時、\n「五月雨美女 “が” さ乱れる」じゃなくて\n「五月雨美女 “がさ” 乱れる」かもしれない説が\nメンバー内で浮上したんだよな…😂"}, {"date": "2026/05/09", "url": "https://x.com/karin__miyamoto/status/2052897451183624504", "song": "上手く言えない", "artist": "アンジュルム", "text": "今日、寝てる時に\n急に夢の中で流れてきた…謎😂\n\nハロコンのみんな\nすごいかっこよかったなぁ☺️"}, {"date": "2026/05/08", "url": "https://x.com/karin__miyamoto/status/2052593941128843535", "song": "セクシーキャットの演説", "artist": "モーニング娘。'16", "text": "猫の衣装いいなぁ…って\n当時の宮本は思ってました😂\n\n2016年ってJuice=Juice何してたっけ！？"}, {"date": "2026/05/06", "url": "https://x.com/karin__miyamoto/status/2051836415861018871", "song": "HAPPY!Stand Up", "artist": "Berryz工房", "text": "客席を指さす振り付けが大量にあるから\nもしかして…今、指さし貰った…？って\n勘違いできる曲で大好き🫶"}, {"date": "2026/05/05", "url": "https://x.com/karin__miyamoto/status/2051453237149216864", "song": "愛のバカやろう", "artist": "後藤真希", "text": "一時期ハロコン常連曲だったイメージ。\n\nめっちゃ音程とるのむずい曲だし\nオケにハロプロ好きの血騒いでしまう！！"}, {"date": "2026/05/04", "url": "https://x.com/karin__miyamoto/status/2051101470632955997", "song": "WOW WOW WOW", "artist": "プッチモニ", "text": "ライブでめっちゃ盛り上がるんだよねええ！！\n何気に歌ったことはない楽曲！\n\n「公演を歩きたい」って歌詞に\nめっちゃつんく♂さん感じる。笑"}, {"date": "2026/05/03", "url": "https://x.com/karin__miyamoto/status/2050725672927269047", "song": "MOON POWER", "artist": "Berryz工房", "text": "舞台「3億円少女」のテーマソング！\n\n全役回替わり…\n皆さんすごく大変そうでした…😳"}, {"date": "2026/05/02", "url": "https://x.com/karin__miyamoto/status/2050345274015612951", "song": "DON'T STOP 恋愛中", "artist": "T&Cボンバー", "text": "このイントロの不思議な感じと\n鬼リズムむずすぎ曲な感じ\nだぁいすきです☺️"}, {"date": "2026/05/01", "url": "https://x.com/karin__miyamoto/status/2050045210529615965", "song": "お願い魅惑のターゲット", "artist": "メロン記念日", "text": "この曲で「コラー！」が言えたら\nようやくハロプロのディープファンになった実感\n湧くと思ってる😂\n\n詳しいことは誰かがリプ欄で説明してくれる😂"}, {"date": "2026/04/30", "url": "https://x.com/karin__miyamoto/status/2049666977300619558", "song": "マジカルフューチャー！", "artist": "Berryz工房", "text": "個人的ハロプロ曲\nイントロわくわくランキング作ったら\n絶対上位に来ちゃいそうな曲😌"}, {"date": "2026/04/29", "url": "https://x.com/karin__miyamoto/status/2049276405712818338", "song": "ペンペン兄弟", "artist": "新ミニモニ。", "text": "やっと追加された！\n\n覚えてきたから\n「歌詞カードいりません！」ってレコーディングで言っちゃった曲。笑\n当時小5😂\n写真の中から私を探してみて～✨"}, {"date": "2026/04/28", "url": "https://x.com/karin__miyamoto/status/2048940214778024153", "song": "胸さわぎスカーレット", "artist": "Berryz工房", "text": "おすすめに流れてきたので選曲。\n\nイントロの男性の声の感じのハロプロ曲から得られる栄養があると思うのです。"}, {"date": "2026/04/27", "url": "https://x.com/karin__miyamoto/status/2048721398387130810", "song": "HELLO TO YOU〜ハロー！プロジェクト10周年記念テーマ〜", "artist": "モーニング娘。", "text": "周年曲の中では影薄めかもだけど\n私はかなり好き。\n\nもっと聴かれてほしい☺️"}, {"date": "2026/04/26", "url": "https://x.com/karin__miyamoto/status/2048189909266260453", "song": "エイヤサ！ブラザー", "artist": "メロウクアッド", "text": "面白かっこいい曲ランキング作ったら\n上位だと思う。\n\n個人的に\n平成のソーラン節だと思ってる！😂"}, {"date": "2026/04/25", "url": "https://x.com/karin__miyamoto/status/2047843806230536572", "song": "直感2〜逃した魚は大きいぞ！〜", "artist": "モーニング娘。", "text": "活きのいい魚を抱えてたら\n逃げられちゃった！\nっていう振り付けがあって\nめっちゃ面白いからライブ見てほしい😂\n\nあとY2Kブームの今\nこのジャケット可愛いすぎ！"}, {"date": "2026/04/24", "url": "https://x.com/karin__miyamoto/status/2047513630657368519", "song": "Borderline", "artist": "Juice=Juice", "text": "この曲の初披露\n武道館公演の1曲目だったんだけど\n\n小さめのステージに\nみんなで乗ってたから\n誰か落ちるのでは！？って\nずっと怖かった記憶😂"}, {"date": "2026/04/23", "url": "https://x.com/karin__miyamoto/status/2047084567136526828", "song": "What's Up？ 愛はどうなのよ〜", "artist": "モーニング娘。", "text": "オーディションで歌った気がする…！\n\nサビ最後の\n「愛はここにある」の主メロが\nどうしてもハモリの方に聞こえちゃって\nめっちゃ苦しんだ記憶😂"}, {"date": "2026/04/22", "url": "https://x.com/karin__miyamoto/status/2046737486404272397", "song": "横浜蜃気楼", "artist": "後藤真希", "text": "この曲のバックダンス\nめっちゃ激しかった記憶…！\n\nバックダンサー思い出曲セトリ\nいつか作りたいなぁ😌"}, {"date": "2026/04/20", "url": "https://x.com/karin__miyamoto/status/2046011729671536680", "song": "好きな先輩", "artist": "モーニング娘。", "text": "初めてのライブ（たぶん小5）で\n歌わせていただいた曲。\n\n覚えられないかも…って\n先行リハしてもらったなぁ😂"}, {"date": "2026/04/19", "url": "https://x.com/karin__miyamoto/status/2045657507394453510", "song": "ラッキーオーラ", "artist": "真野恵里菜", "text": "バックダンサーの振り付けも\nめっちゃ可愛いの🥹"}, {"date": "2026/04/18", "url": "https://x.com/karin__miyamoto/status/2045297986545262937", "song": "サンサンGOGO", "artist": "MilkyWay", "text": "「サンサンGOGO」／MilkyWay\nきら☆レボ、毎週の楽しみだったなぁ⭐️"}, {"date": "2026/04/17", "url": "https://x.com/karin__miyamoto/status/2044936933168841120", "song": "ゴール", "artist": "Buono!", "text": "ロックなミディアムテンポって\nこういうことか！ってなった曲。\n\nライブで歌うの\nむずかしそうだなぁとも思う😌"}, {"date": "2026/04/16", "url": "https://x.com/karin__miyamoto/status/2044572057816756468", "song": "ああ、夜が明ける", "artist": "Berryz工房", "text": "ジャケ写の皆さんの前髪に\n平成のオシャレを感じる😌"}, {"date": "2026/04/15", "url": "https://x.com/karin__miyamoto/status/2044201715839447318", "song": "21世紀的恋愛事情", "artist": "真野恵里菜", "text": "コールもめっちゃ楽しい曲！\n\nとっても可愛いのに\nぶりぶりしてなくて\nいくつになっても歌えるなぁって思う😌"}, {"date": "2026/04/14", "url": "https://x.com/karin__miyamoto/status/2043863140677628289", "song": "新・日本のすすめ！", "artist": "スマイレージ", "text": "こんな曲、なかなか出てこないと思う。\nつんく♂さん節のひとつだとも思う！\nみんなが思うつんく♂さん節炸裂曲は？"}, {"date": "2026/04/13", "url": "https://x.com/karin__miyamoto/status/2043489958875541837", "song": "ミニ。ストロベリ～パイ", "artist": "ミニモニ", "text": "新ミニモニ。として披露した時\n「すちょべりーって歌って！」って言われて\n必死に頑張った記憶😂"}, {"date": "2026/04/12", "url": "https://x.com/karin__miyamoto/status/2043141805198512461", "song": "かわいい彼", "artist": "メロン記念日", "text": "定期的に歌われる気がするなぁ😌\n\n私は歌ったことないんだけど\n「ハロプロ聴いてる！」って感じがして\n大好きです！"}, {"date": "2026/04/11", "url": "https://x.com/karin__miyamoto/status/2042775522112082085", "song": "ダイアリー", "artist": "松浦亜弥", "text": "初めてソロで歌ったの\nこの曲だったような…？\n\nあの時は「学園祭って何年後？」って思ってたのに\n今じゃ「何年前？」だなぁ😂"}, {"date": "2026/04/10", "url": "https://x.com/karin__miyamoto/status/2042387757025411128", "song": "桜→入学式", "artist": "Berryz工房", "text": "「おろしたて革靴は 少し窮屈でも」\n\nなんでつんく♂さんそれ知ってるの？？\nってなるやつね、、！"}, {"date": "2026/04/09", "url": "https://x.com/karin__miyamoto/status/2042031772570153002", "song": "フォレフォレ 〜Forest For Rest〜", "artist": "DIY♡", "text": "選ばれし脚長メンバー。\n\nハロメンが\n「ここに入るのは無理」って\n口を揃えて言ってたユニット。笑\n\n足が長すぎるんよ😂"}, {"date": "2026/04/08", "url": "https://x.com/karin__miyamoto/status/2041709363199668677", "song": "シャイニング 愛しき貴方", "artist": "カントリー娘。に紺野と藤本(モーニング娘｡)", "text": "この曲の最初の「バルバ…」って声\nモノマネ選手権をハロプロエッグ内で開催したのが\n忘れられない記憶😂\n\nみんなもつい真似しちゃうハロプロのコーラスある？"}, {"date": "2026/04/07", "url": "https://x.com/karin__miyamoto/status/2041415070161490041", "song": "黄色い自転車とサンドウィッチ", "artist": "スマイレージ", "text": "なんか自転車のハンドルついた\nマイクスタンドで歌ってたこと\nあったような…？笑\n\n覚えてる人いる？"}, {"date": "2026/04/06", "url": "https://x.com/karin__miyamoto/status/2040962948492145017", "song": "VERY BEAUTY", "artist": "Berryz工房", "text": "この歌、歌えたら歌うまだと思ってた曲。\n\nサビが\n裏声と地声（ファルセットとチェスト）を\n行ったり来たりするので\nめっちゃ難しいです。"}, {"date": "2026/04/05", "url": "https://x.com/karin__miyamoto/status/2040589735899591072", "song": "会えない長い日曜日", "artist": "藤本美貴", "text": "2週間くらい日曜日みんなに会えなかったので😌\n\nどんな日曜日を過ごす予定ですか？"}, {"date": "2026/04/04", "url": "https://x.com/karin__miyamoto/status/2040234713508720985", "song": "記憶の迷路", "artist": "High-King", "text": "ハロプロのエモ感が詰まってる曲。\n\nコールもできる最強の曲なのに\nカップリングなんだよね…！！"}, {"date": "2026/04/02", "url": "https://x.com/karin__miyamoto/status/2039520129005093190", "song": "Ça va ? Ça va ?", "artist": "Juice=Juice", "text": "Juice=Juiceで一番披露されてないのって、この曲？\n\n最後のセリフ、オーディションだったんだけど宮本勝ち取りました😌"}, {"date": "2026/04/01", "url": "https://x.com/karin__miyamoto/status/2039182085345390984", "song": "銀色の永遠", "artist": "藤本美貴", "text": "MIKI①ってほんとうに名盤…\n\n暗いのか明るいのか分からない\n素敵な曲ランキング上位😌\n\nいつか絶対歌いたいのに\nセトリに入りづらいランキングでも上位。😂"}, {"date": "2026/03/31", "url": "https://x.com/karin__miyamoto/status/2038779146189557895", "song": "恋する♡エンジェル♡ハート", "artist": "美勇伝", "text": "ハロプロエッグといえばこの曲、って気持ちになるけど\n「ハロプロエッグといえば」の曲がありすぎる😂\n\nみんなにとって\nハロプロエッグといえばの曲、なに？"}, {"date": "2026/03/30", "url": "https://x.com/karin__miyamoto/status/2038420138790457685", "song": "スイーーツ→→→ライブ", "artist": "℃-ute", "text": "かなり若いうちに\n前日の夕食から調整して\nスイーツバイキング行ってみたかったなぁ。笑"}, {"date": "2026/03/29", "url": "https://x.com/karin__miyamoto/status/2038105519601365332", "song": "笑っちゃおうよ BOYFRIEND", "artist": "Berryz工房", "text": "前髪なくても薄くても\n全員ビジュ爆発してるの\nヤバすぎる…"}, {"date": "2026/03/28", "url": "https://x.com/karin__miyamoto/status/2037693137616064585", "song": "さくら満開", "artist": "モーニング娘。さくら組", "text": "この曲、なんだかんだ\nセンス持って披露したことない気がする…！\n\nなんだかんだ\n私、センスに縁がないな？笑"}, {"date": "2026/03/27", "url": "https://x.com/karin__miyamoto/status/2037329602402828526", "song": "I surrender 愛されど愛", "artist": "モーニング娘。'19", "text": "これ、ハロコンで歌ったことある気がする…？\n記憶違いかな😂\n\nそれと20thアルバムのジャケット\n1stベストのデザイン踏襲してたんだね！今知った！"}, {"date": "2026/03/26", "url": "https://x.com/karin__miyamoto/status/2036957134567678011", "song": "愛・愛・傘", "artist": "Juice=Juice", "text": "傘を持ってパフォーマンスした時\nマイクの電波が傘の影響でうまく飛ばなくなる\nっていうトラブルがあったのを\n唐突に思い出しました😂"}, {"date": "2026/03/25", "url": "https://x.com/karin__miyamoto/status/2036603662865408326", "song": "エイティーン エモーション", "artist": "スマイレージ", "text": "これ、18歳がいないと歌えない気がする😂\n好きだったのに18歳で歌い損ねた気がする…\n\n年齢が入ってるハロプロ曲、他にもある？"}, {"date": "2026/03/24", "url": "https://x.com/karin__miyamoto/status/2036235173298336091", "song": "君の戦法", "artist": "℃-ute", "text": "めっちゃ可愛い曲。\n\n宮崎由加ちゃんが\n持ち歌かのようにたくさん歌ってた記憶があるんだけど\nあれって練習してただけ…？笑\n\n生で聴いたの、カバーだけかも。"}, {"date": "2026/03/23", "url": "https://x.com/karin__miyamoto/status/2035908088591749417", "song": "サヨナラのかわりに", "artist": "モーニング娘。", "text": "おはスタでめっちゃ聴いてた記憶…！\n\nタイトル的に卒業コンサートっぽくなりそうなのに\nあんまり「卒業曲感」ないのは\nなんでなんだろう？"}, {"date": "2026/03/22", "url": "https://x.com/karin__miyamoto/status/2035494362126389291", "song": "大阪 恋の歌", "artist": "モーニング娘。", "text": "今日は京都でLIVEなのに\nなぜかこの歌が浮かんできたので…笑\n\n地名が入ってるハロプロ曲って\n他にもある？"}, {"date": "2026/03/21", "url": "https://x.com/karin__miyamoto/status/2035107820987981996", "song": "ミニモニ。ひなまつり！", "artist": "ミニモニ。", "text": "なんだかんだ\n歌ったことはない曲なんだけど\n\nひなフェスが来ると\n絶対思い出しちゃう😂\n\nみんなの「ひなフェスの思い出曲」ある？"}, {"date": "2026/03/20", "url": "https://x.com/karin__miyamoto/status/2034768743147217173", "song": "桜ナイトフィーバー", "artist": "こぶしファクトリー", "text": "多分今年のひなフェスも歌う、、？\n\nこの曲、発売してから\nひなフェスで歌わなかった年ってあるの…！？"}, {"date": "2026/03/19", "url": "https://x.com/karin__miyamoto/status/2034408397559463991", "song": "花、闌の時", "artist": "ハロプロ・オールスターズ", "text": "懐かしい…\n\nハロコンの日の朝に\n全員で舞台に集合して撮影したなぁ…\n\n曲調も相まって\nみんなで眠かった記憶。笑\n\nこれって、ライブで披露したんだっけ？"}, {"date": "2026/03/18", "url": "https://x.com/karin__miyamoto/status/2034065000747372602", "song": "ブラボー！", "artist": "モーニング娘。", "text": "そんなに卒業ソングって感じでもないのに\n卒業感を感じる曲。\n\n卒コン感あるんだよなぁ、、\n\nみんなはどの卒コン思い出す？"}, {"date": "2026/03/16", "url": "https://x.com/karin__miyamoto/status/2033369403065356726", "song": "元気ピカッピカッ！", "artist": "モーニング娘。", "text": "キラキラした曲といえば\n私はこれだと思ってる✨\n\nBメロの振りが\nコールと同じクラップなのが\n楽しくて好き！"}, {"date": "2026/03/15", "url": "https://x.com/karin__miyamoto/status/2032972373499203755", "song": "ジンギスカン", "artist": "Berryz工房", "text": "最初に出会ったのがBerryz工房さんverだったから\nずっとオリジナルだと思ってたけど\n実はカバーだった曲。笑\n\nこの曲を\nかっこ可愛くパフォーマンスできちゃうのが\nハロプロって感じする😂"}, {"date": "2026/03/14", "url": "https://x.com/karin__miyamoto/status/2032635069836439909", "song": "青空がいつまでも続くような未来であれ！", "artist": "モーニング娘。", "text": "全員曲で絶対やったことある曲だったなぁ😂\n\n今のハロコンで\n「全員曲あるある」って言ったら\nみんなどの曲思い浮かぶ？"}, {"date": "2026/03/13", "url": "https://x.com/karin__miyamoto/status/2032250683706261635", "song": "黄色いお空で BOOM BOOM BOOM", "artist": "黄色5", "text": "ハロコンやカバー率が\nすっごい高い曲。\n\nなぜかJuice=Juiceも\nツアーでカバーさせていただいたことあります。"}, {"date": "2026/03/12", "url": "https://x.com/karin__miyamoto/status/2031900786247245881", "song": "Our Songs", "artist": "Buono!", "text": "なにかのオーディションで歌った記憶。\n受からなかったけど\nこの曲、めちゃくちゃ練習したなぁ…！ってふと思い出した。"}, {"date": "2026/03/10", "url": "https://x.com/karin__miyamoto/status/2031163570394943531", "song": "可能性のコンチェルト", "artist": "つばきファクトリー", "text": "この曲、作曲が n-buna さんなんです！\n（ヨルシカの n-buna さん！）\n\nアイドル×ボカロPの化学反応って\nやっぱりアツい。\n\nみんなの「この組み合わせ最高…！」なハロプロ曲ある？"}, {"date": "2026/03/09", "url": "https://x.com/karin__miyamoto/status/2030826221370757195", "song": "雨の降らない星では愛せないだろう？", "artist": "モーニング娘。", "text": "実力診断テストで歌った記憶。\n\nバラードなのに\n16ビートを感じられるのが\nハロプロだ…ってなって好き😌\n\nみんなの好きなハロプロバラードある？"}, {"date": "2026/03/08", "url": "https://x.com/karin__miyamoto/status/2030426855577452850", "song": "日曜日は大好きよ", "artist": "℃-ute", "text": "つんく♂さん、日曜日の歌好きですよね！？！？笑\n\nこの時期の℃-uteさんの\n全員が！センターです！！\nみたいな感じが大好きでした😌\n\nみんなの「日曜日といえば」なハロプロ曲ある？"}, {"date": "2026/03/07", "url": "https://x.com/karin__miyamoto/status/2030087391516709199", "song": "ショートカット", "artist": "スマイレージ", "text": "私の中で一番好き！ってなる衣装。\n\n断髪式の様子、テレビで見たなぁ。\nみんなどんな髪型でも可愛すぎた…\n\nみんなの「一番好き！」なハロプロ衣装ある？"}, {"date": "2026/03/06", "url": "https://x.com/karin__miyamoto/status/2029738530625429809", "song": "想いあふれて", "artist": "松浦亜弥", "text": "幼い頃から\n唐突に聴きたくなる日がある曲。\n\n松浦さんの歌声は\n宮本佳林の世界に\nなくてはならないものすぎる。"}, {"date": "2026/03/05", "url": "https://x.com/karin__miyamoto/status/2029375439098311032", "song": "お昼の休憩時間。", "artist": "Berryz工房", "text": "Berryz工房さんで一番好きな曲は？って聞かれたら\nこの曲選ぶかもしれないってくらい好き。\n\n色々聞かれるのに\nちゃんと順番制なのが面白い歌詞。笑\n\nみんなのBerryz工房で「1番かも」な曲ある？"}, {"date": "2026/03/04", "url": "https://x.com/karin__miyamoto/status/2028985299909693819", "song": "ふわり、恋時計", "artist": "つばきファクトリー", "text": "曲が素敵すぎて\nちょっと羨ましかった曲。\n\n「ふわり、恋時計」／つばきファクトリー\n\n間奏の まおぴん（秋山眞緒ちゃん）ターンは\n見逃し厳禁です…！\n\nみんなが「素敵！」ってなったハロプロ曲も教えて！"}, {"date": "2026/03/03", "url": "https://x.com/karin__miyamoto/status/2028638577190748404", "song": "スクリーン", "artist": "安倍なつみ", "text": "ハロプロのテレビ番組を見てた時、\nCMで流れてきて\n\nうわ…素敵な曲…って\n一瞬で心つかまれた記憶。\n\n小4か小5くらいだったなぁ。"}, {"date": "2026/03/02", "url": "https://x.com/karin__miyamoto/status/2028267035755717109", "song": "春の嵐", "artist": "真野恵里菜", "text": "この曲で初めて\n“リリースイベント”というものを体験しました！\n\nいつか私もこんなイベントがしたい！って思ったなぁ。\nその夢が叶えられてる今が、幸せです。"}, {"date": "2026/03/01", "url": "https://x.com/karin__miyamoto/status/2027902507876581459", "song": "LOVE LIKE CRAZY", "artist": "後浦なつみ", "text": "宮本が「かっこいい」に分類された曲。\n\nJuice=JuiceがCUTE・COOL・SEXYに分かれた時に\nこの曲でCOOL担当でパフォーマンスしました！\n\n片方イヤリング取れて\n気付かれないように外した記憶。笑"}, {"date": "2026/02/28", "url": "https://x.com/karin__miyamoto/status/2027568761046450186", "song": "天気予報があたったら", "artist": "真野恵里菜", "text": "バックダンサーで踊らせてもらった曲の中でも\nすごく印象深い1曲。\n\n爽やかロックサウンドなのに\n主人公がちゃんと女の子で\n大好きなんだ～🫶"}, {"date": "2026/02/27", "url": "https://x.com/karin__miyamoto/status/2027175732791947273", "song": "シャイニング バタフライ", "artist": "ドリームモーニング娘。", "text": "ドリムス。さんのコンサートを研修生で見に行って\n階段を見ずに下りる技術もカメラアピールも\n全部が職人技だった…\n\nみんなのハロプロで職人技だと思った瞬間ある？"}, {"date": "2026/02/26", "url": "https://x.com/karin__miyamoto/status/2026808428056948890", "song": "安心感", "artist": "Berryz工房", "text": "この曲、今のSNSで鬼バズりすると思う。\n\nなんどだって「好き」と言われたい\nいつだって 安心したい\n\n真っ直ぐすぎて\n逆に今めちゃくちゃ刺さる。\n\nつんく♂さん最先端すぎ！"}, {"date": "2026/02/25", "url": "https://x.com/karin__miyamoto/status/2026453317573136785", "song": "憧れのStress-free", "artist": "ハロプロ・オールスターズ", "text": "ライブで披露したことがない曲。\n\nライブで披露したことないけど\nめっちゃいい曲。\n\nこの時のオールスター、\n懐かしすぎるなぁ。"}, {"date": "2026/02/24", "url": "https://x.com/karin__miyamoto/status/2026088357181448631", "song": "Feel！感じるよ", "artist": "Juice=Juice", "text": "一番暴風だったMV。\n\n崖みたいな場所での撮影で\n暴風＆極寒すぎて\n\n呼ばれても\nみんなロケバスから\nなかなか降りられませんでした😂"}, {"date": "2026/02/23", "url": "https://x.com/karin__miyamoto/status/2025754807441777103", "song": "私がすることない程 全部してくれる彼", "artist": "Berryz工房", "text": "最強の気遣いを\nつんく♂さんが教えてくれた曲。\n\n「私も何かしてあげたい\nそんな乙女心まで見てね」\n\n先回りすることが\n全てじゃないんだって\n幼い頃学びました。"}, {"date": "2026/02/22", "url": "https://x.com/karin__miyamoto/status/2025374349235290568", "song": "初めてのロックコンサート", "artist": "モーニング娘。", "text": "いつか歌いたいと思っていて\nタイミング逃し続けて大人になってしまった曲。\n\n暗い曲？って思わせる入りなのに\nめっちゃフレッシュな恋歌なのが大好き。"}, {"date": "2026/02/21", "url": "https://x.com/karin__miyamoto/status/2025023626823848392", "song": "ロマンスの途中", "artist": "Juice=Juice", "text": "実はこのMV\n同じセットで2回撮影していて\n\n髪の長さが違う宮本が見られます✂️\n\n公開したら気付かれると思ってたのに\nあんまり気付かれなかったんだよね。😂\n\n今見たら気付くかも…？"}, {"date": "2026/02/20", "url": "https://x.com/karin__miyamoto/status/2024628984353566862", "song": "思い立ったら 吉でっせ！", "artist": "Berryz工房", "text": "初めてセンターもらった曲。\n「思い立ったら 吉でっせ！」／Berryz工房\n\n研修生になってすぐの新人公演で\n全員曲のセンター任せてもらってたの…！\n\nサビの振り、体力勝負だったなぁ😌\n当時の写真📸私小5😂"}, {"date": "2026/02/19", "url": "https://x.com/karin__miyamoto/status/2024276823950176301", "song": "Hand made CITY", "artist": "モーニング娘。", "text": "関係者席が悔しかった曲。\n横浜アリーナの～ライバル サバイバル～\nを見ていた時、\n研修生で静かに座ってた私、うずうず😂\nみんなが声出したい曲教えて！\n(URL間違っていたので再掲)"}, {"date": "2026/02/18", "url": "https://x.com/karin__miyamoto/status/2023949899939577876", "song": "リボーン〜命のオーディション〜", "artist": "リボーンイレブン", "text": "初回からマイナー曲！\n“ちゃんさん”のきっかけミュージカルソング😂\n写真も発掘したよ📸\n鞘師里保ちゃんも宮本も幼いね😂\nみんなの今日の1曲も #私の1日1ハロ で教えて！"}]</script>
